mapper.update:
update team_workspace_export_items set status=#{status}, file_count=#{fileCount},
    uncompressed_bytes=#{uncompressedBytes}, shard_bytes=#{shardBytes},
    shard_sha256=#{shardSha256}, error_code=#{errorCode}, error_message=#{errorMessage},
    lease_owner=null, lease_token=null, lease_expires_at=null, updated_at=#{updatedAt}
where export_item_id=#{exportItemId}

update team_workspace_export_items set status='RUNNING', lease_owner=#{leaseOwner},
    lease_token=#{leaseToken}, lease_expires_at=#{leaseExpiresAt}, updated_at=#{now}
where export_item_id=#{exportItemId}
  and status='QUEUED'
  and (lease_expires_at is null or lease_expires_at <= #{now})

mapper.select:
select  from team_workspace_export_jobs
where coordinator_linux_server_id = #{coordinatorLinuxServerId}
  and (
      status = 'CANCELLED'
      or (expires_at <= #{now} and status in ('READY','PARTIAL_READY','FAILED'))
  )
order by expires_at limit #{limit}
